-- ============================================================================
-- 06_areas_prioritarias_e_sbn.sql — SIGWEB SBN Maricá
--
-- Cria e preenche, de uma vez só:
--   tema_estrategico . . . . . 5 temas estratégicos
--   areas_prioritarias . . . . 60 polígonos (EPSG:31983), vindos do areas_60.gpkg
--   area_tema  . . . . . . . . vínculo N:N (uma área pode ter vários temas)
--   sbn_grupo_funcional / sbn_funcao / sbn_solucao / sbn_solucao_funcao
--   views em EPSG:4326 e funções RPC com argumentos tipados, para o site
--
-- A geometria vai embutida em WKB hexadecimal: NÃO é preciso ogr2ogr, nem senha,
-- nem Session pooler. Basta colar este arquivo no SQL Editor do Supabase e rodar.
--
-- O script é IDEMPOTENTE: pode rodar de novo sem duplicar nada.
-- ============================================================================

-- PostGIS vive no schema "extensions" no Supabase: sem isto, ST_* e o tipo
-- geometry não são encontrados.
set search_path = public, extensions;

-- ---------------------------------------------------------------- 1. TEMAS
create table if not exists public.tema_estrategico (
  id          smallint primary key,
  nome        text not null,
  nome_curto  text not null,
  cor         text not null check (cor ~ '^#[0-9a-fA-F]{6}$'),
  ordem       smallint not null
);

insert into public.tema_estrategico (id, nome, nome_curto, cor, ordem) values
  (1, 'Gestão das Águas Urbanas e Redução de Alagamentos', 'Águas Urbanas', '#1f78b4', 1),
  (2, 'Estabilidade do Terreno e Controle da Erosão', 'Terreno e Erosão', '#d95f02', 2),
  (3, 'Resiliência Costeira e Lagunar e Recuperação de Sistemas Naturais', 'Costeira e Lagunar', '#00a0b0', 3),
  (4, 'Infraestrutura Verde, Biodiversidade e Conforto Térmico', 'Infraestrutura Verde', '#66a61e', 4),
  (5, 'Saneamento Ecológico e Redução da Vulnerabilidade Urbana', 'Saneamento Ecológico', '#7570b3', 5)
on conflict (id) do update set nome = excluded.nome, nome_curto = excluded.nome_curto,
  cor = excluded.cor, ordem = excluded.ordem;

-- --------------------------------------------------- 2. ÁREAS PRIORITÁRIAS
-- Geometria MULTIPOLYGON em EPSG:31983 (SIRGAS 2000 / UTM 23S), o mesmo SRC
-- das demais tabelas: nada a reprojetar na carga.
create table if not exists public.areas_prioritarias (
  num_area  smallint primary key,
  area_ha   numeric(12,4),
  geom      geometry(MultiPolygon, 31983) not null
);

