-- Corrige auto-interseções e anéis mal fechados, que quebrariam ST_Intersects,
-- ST_Area e a própria publicação da camada.
update public.areas_prioritarias
   set geom = ST_Multi(ST_CollectionExtract(ST_MakeValid(geom), 3))
 where not ST_IsValid(geom);

create index if not exists areas_prioritarias_geom_gix
  on public.areas_prioritarias using gist (geom);

-- ------------------------------------------------ 3. VÍNCULO ÁREA <-> TEMA
-- N:N porque uma área pode receber mais de um tema (24 áreas têm 2 temas e 3 têm 3).
create table if not exists public.area_tema (
  num_area  smallint not null references public.areas_prioritarias(num_area) on delete cascade,
  tema_id   smallint not null references public.tema_estrategico(id)        on delete cascade,
  primary key (num_area, tema_id)
);

