-- ------------------------------------------------- 4. CATÁLOGO DE SOLUÇÕES
create table if not exists public.sbn_grupo_funcional (
  id    smallint generated always as identity primary key,
  nome  text not null unique
);

-- Vocabulário controlado: são exatamente as 20 células da grade da ficha-modelo.
create table if not exists public.sbn_funcao (
  id     smallint primary key,
  ordem  smallint not null,
  nome   text not null unique
);

insert into public.sbn_funcao (id, ordem, nome) values
  (1, 1, 'Armazenamento temporário'),
  (2, 2, 'Infiltração'),
  (3, 3, 'Filtragem'),
  (4, 4, 'Tratamento da água'),
  (5, 5, 'Tratamento de efluentes'),
  (6, 6, 'Condução lenta'),
  (7, 7, 'Controle do escoamento superficial'),
  (8, 8, 'Retenção de sedimentos'),
  (9, 9, 'Dissipação de energia'),
  (10, 10, 'Estabilização do solo'),
  (11, 11, 'Controle da erosão'),
  (12, 12, 'Proteção de margens'),
  (13, 13, 'Proteção costeira'),
  (14, 14, 'Recomposição vegetal'),
  (15, 15, 'Arborização e sombreamento'),
  (16, 16, 'Recuperação de áreas úmidas'),
  (17, 17, 'Recuperação de ecossistemas'),
  (18, 18, 'Conectividade ecológica'),
  (19, 19, 'Qualificação paisagística'),
  (20, 20, 'Produção comunitária')
on conflict (id) do update set nome = excluded.nome, ordem = excluded.ordem;

create table if not exists public.sbn_solucao (
  id                      smallint primary key,
  tema_id                 smallint not null references public.tema_estrategico(id),
  slug                    text not null unique,
  nome                    text not null,
  ordem                   smallint not null,
  descricao               text,
  tipologia               smallint,
  grupo_funcional_id      smallint references public.sbn_grupo_funcional(id),
  ameaca_climatica        text,
  desafio_ambiental       text,
  beneficios_ambientais   text,
  beneficios_sociais      text,
  beneficios_economicos   text,
  restricoes              text,
  escala_aplicacao        text,
  aplicacao               text,
  complexidade            text,
  manutencao              text,
  custo                   text,
  custo_unidade           text,
  -- Campos propostos, ainda sem dado na planilha (ver README):
  tempo_resultado         text,
  referencias             text,
  ilustracao_url          text,
  status_conteudo         text,
  status_ilustracao       text
);

insert into public.sbn_grupo_funcional (nome) values
  ('Drenagem, filtragem e infiltração'),
  ('Estabilidade do terreno e controle da erosão'),
  ('Infraestrutura verde, biodiversidade e conforto térmico'),
  ('Recuperação costeira e sistemas naturais'),
  ('Recuperação hídrica e de margens'),
  ('Retenção e armazenamento'),
  ('Saneamento ecológico e produção comunitária')
on conflict (nome) do nothing;

insert into public.sbn_solucao (id, tema_id, slug, nome, ordem, descricao, tipologia,
    grupo_funcional_id, ameaca_climatica, desafio_ambiental, beneficios_ambientais,
    beneficios_sociais, beneficios_economicos, restricoes, escala_aplicacao, aplicacao,
    complexidade, manutencao, custo, custo_unidade, status_conteudo, status_ilustracao) values
  (1, 1, 'jardim-filtrante', 'Jardim filtrante', 1, 'Canteiro vegetado composto por camadas de substrato e materiais filtrantes, destinado ao tratamento de águas pluviais ou águas com carga poluente por meio da retenção de sólidos, da filtragem e da absorção de nutrientes pela vegetação. Pode ser implantado próximo a pontos de lançamento de drenagem, estacionamentos, praças e equipamentos públicos, contribuindo para melhorar a qualidade da água antes de sua chegada aos corpos hídricos.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   'Inundação e Alagamentos', 'Poluição hídrica; aporte de sedimentos; poluentes difusos.',
   'Melhoria da qualidade da água; retenção de sedimentos e poluentes; redução da carga de nutrientes; recuperação de funções ecológicas; apoio à biodiversidade.',
   'Qualificação de espaços públicos; melhoria da ambiência urbana; redução da exposição a águas degradadas; educação ambiental.',
   'Redução de custos de limpeza, desassoreamento e tratamento da água; possibilidade de implantação gradual; redução de danos associados à degradação hídrica.',
   'Planície aluvial ou corpo hídrico a menos de 50 m: estrutura estanque com dreno. Não deve receber esgoto.', 'Lote / Logradouro, Praça / Área livre, Equipamento público / Área institucional',
   'Pontos de lançamento, estacionamentos, praças e entorno de equipamentos públicos.', 'Baixa', 'Média', 'R$ 400,00 a R$ 700,00/ m² *', 'm²', 'Concluído', 'Pendente'),
  (2, 1, 'biovaleta', 'Biovaleta', 2, 'Depressão linear rasa e vegetada que recebe e conduz lentamente o escoamento superficial, favorecendo a infiltração e a retenção de sedimentos e poluentes. É indicada para canteiros centrais, bordas de vias, estacionamentos e outros espaços lineares, podendo complementar ou substituir trechos de sarjetas e valas de terra, conforme as condições locais, e ser integrada a poços e trincheiras de infiltração.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   'Inundação e Alagamentos', 'Escoamento superficial acelerado; alagamentos localizados; transporte de sedimentos e poluentes.',
   'Redução da velocidade do escoamento superficial; retenção de sedimentos e parte dos poluentes difusos; ampliação da infiltração quando adequada; aumento da cobertura vegetal; apoio à biodiversidade urbana.',
   'Qualificação de vias, estacionamentos e espaços públicos; melhoria da ambiência urbana; redução de empoçamentos nos trechos atendidos; oportunidades de educação ambiental sobre o percurso das águas.',
   'Possível redução dos custos de limpeza e desobstrução da drenagem; redução de danos associados à erosão; possibilidade de implantação integrada a obras viárias; diminuição da solicitação da rede convencional.',
   'Verificar declividade e saídas; evitar infiltração em solo contaminado ou instável; não receber esgoto', 'Lote / Logradouro, Praça / Área livre',
   'Bordas de vias, canteiros centrais e faixas lineares', 'Baixa', 'Média', 'R$ 200,00 a R$ 500,00/m²', 'm²', 'Concluído', 'Pendente'),
  (3, 1, 'jardim-de-chuva', 'Jardim de chuva', 3, 'Depressão vegetada que recebe o escoamento de telhados, calçadas, vias e outras superfícies impermeáveis, promovendo o armazenamento temporário, a filtragem e a infiltração da água no solo. Pode ser implantada em praças, parques, áreas livres de equipamentos públicos e recuos de lotes, contribuindo para reduzir o volume de água encaminhado à drenagem convencional, além de ampliar a vegetação e qualificar a paisagem urbana.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Impermeabilização do solo; aumento do escoamento superficial; poluição difusa da drenagem.',
   'Redução do volume de escoamento superficial; retenção de sedimentos e parte dos poluentes difusos; melhoria da qualidade das águas pluviais; ampliação da infiltração quando as condições locais permitem; aumento da cobertura vegetal e apoio à biodiversidade urbana.',
   'Qualificação de espaços públicos; melhoria da ambiência urbana; contribuição para reduzir alagamentos localizados; ampliação do contato com a vegetação; oportunidades de educação ambiental sobre o manejo das águas.',
   'Redução potencial de danos associados a alagamentos; diminuição da sobrecarga da drenagem convencional; possível redução de custos de limpeza e desassoreamento a jusante; possibilidade de implantação gradual e integrada a obras de urbanização e requalificação de espaços públicos.',
   'Solos com baixa capacidade de infiltração; lençol freático raso; terrenos contaminados ou sujeitos à instabilidade; proximidade de fundações e redes subterrâneas sem avaliação técnica; ausência de saída segura para vazões excedentes. Não deve receber esgoto ou efluentes sem tratamento.', 'Lote / Logradouro, Logradouro / Via, Praça / Área livre, Equipamento público / Área institucional, Parque / Área verde',
   'Recuos de lotes, bordas de vias, estacionamentos, praças, parques e áreas livres de equipamentos públicos, recebendo o escoamento de telhados, calçadas e outras superfícies impermeáveis.', 'Baixa', 'Média', 'R$ 400,00 a R$ 700,00/m²', 'm²', 'Concluído', 'Pendente'),
  (4, 1, 'canteiro-pluvial-com-infiltracao', 'Canteiro pluvial com infiltração', 4, 'Estrutura vegetada rebaixada, delimitada por bordas e preenchida com substrato filtrante, que recebe o escoamento de vias, calçadas e telhados, armazenando-o temporariamente e favorecendo sua filtragem e infiltração no solo. É indicada para pequenos espaços urbanos, como faixas de serviço de calçadas e áreas junto ao meio-fio, desde que haja permeabilidade adequada, nível do lençol freático suficientemente profundo e afastamento seguro de fundações e redes subterrâneas.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Impermeabilização de pequenos espaços; redução da infiltração; aumento do escoamento local.',
   'Armazenamento temporário próximo à origem do escoamento; retenção de sólidos e parte dos poluentes; ampliação da infiltração em solos compatíveis; aumento da cobertura vegetal em áreas pavimentadas.',
   'Qualificação de calçadas e espaços junto às vias; melhoria da paisagem e da ambiência urbana; redução de empoçamentos nos pontos atendidos; oportunidades de educação ambiental.',
   'Integração da drenagem às obras de calçadas e urbanização; possibilidade de implantação por etapas; redução potencial de danos e de sobrecarga da rede; aproveitamento de pequenas áreas disponíveis.',
   'Solo permeável e separação adequada do lençol; verificar redes, fundações, acessibilidade e extravasamento', 'Lote / Logradouro, Praça / Área livre',
   'Faixas de serviço e áreas junto ao meio-fio', 'Baixa', 'Média', 'R$ 400,00 a R$ 800,00/m²', 'm²', 'Concluído', 'Pendente'),
  (5, 1, 'canteiro-pluvial-sem-infiltracao', 'Canteiro pluvial sem infiltração', 5, 'Estrutura vegetada rebaixada, com fundo impermeabilizado e sistema de drenagem, que recebe e armazena temporariamente o escoamento superficial, promovendo sua filtragem biológica e liberação controlada para a rede de drenagem, sem infiltração no terreno. É indicada para locais com solos pouco permeáveis, lençol freático raso ou restrições à infiltração, como áreas próximas a fundações e redes subterrâneas, contribuindo para reduzir os picos de vazão e reter parte dos poluentes transportados pela água.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Escoamento em áreas pouco permeáveis; alagamentos localizados; transporte de poluentes superficiais pela drenagem.',
   'Melhoria da qualidade da água; Recarga do lençol freático; Proteção dos ecossistemas.',
   'Valorização de espaços de implantação; melhoria da paisagem e da ambiência urbana; redução do risco de enchentes e alagamentos.',
   'Redução de custos com danos e recuperação após enchentes; acesso a incentivos e financiamentos.',
   'Ausência de drenagem e extravasamento seguros; risco de vazamentos junto a fundações; interferências com redes subterrâneas ou acessibilidade. Não deve receber esgoto ou efluentes sem tratamento.', 'Lote / Logradouro, Logradouro / Via, Equipamento público / Área institucional',
   'Calçadas, bordas de vias, estacionamentos, praças e áreas livres com restrições à infiltração.', 'Média', 'Média', 'R$400,00 - R$800,00', null, 'Concluído', 'Pendente'),
  (6, 1, 'poco-de-infiltracao', 'Poço de infiltração', 6, 'Estrutura subterrânea escavada e revestida ou preenchida com material granular, projetada para receber águas pluviais de pequenas áreas de contribuição e favorecer sua infiltração no solo. Por ocupar pouco espaço na superfície, pode ser implantada sob calçadas e em áreas livres, inclusive em associação a outros dispositivos de drenagem sustentável, desde que as condições de permeabilidade, profundidade do lençol freático e qualidade da água sejam adequadas.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Excesso de escoamento em pequenas áreas; redução da infiltração; sobrecarga da drenagem convencional.',
   'Contribuição para a recarga subterrânea quando adequada; menor concentração do escoamento na superfície.',
   'Contribuição para reduzir empoçamentos e alagamentos locais; pequena ocupação da superfície; possibilidade de implantação em áreas urbanas com espaço limitado; melhoria das condições de acesso e circulação nos pontos atendidos.',
   'Aproveitamento de áreas com pouca disponibilidade superficial; integração a obras de drenagem e pavimentação; possível redução da demanda sobre a rede; redução potencial de danos por acúmulo de água.',
   'Não indicado com lençol raso, solo pouco permeável ou contaminado; prever pré-tratamento e acesso; avaliar fundações e estabilidade', 'Lote / Logradouro, Praça / Área livre, Logradouro / Via',
   'Calçadas, estacionamentos e áreas livres de lotes e equipamentos públicos, com solo permeável e lençol freático suficientemente profundo.', 'Média', 'Média', 'R$ 350,00 a R$ 650,00/m²', 'm²', 'Concluído', 'Pendente'),
  (7, 1, 'trincheira-de-infiltracao', 'Trincheira de infiltração', 7, 'Vala linear preenchida com material granular, geralmente envolvido por manta geotêxtil, que armazena temporariamente o escoamento superficial e permite sua infiltração ao longo da extensão. Pode ser implantada junto a vias, calçadas, estacionamentos e limites de lotes, especialmente em projetos de urbanização e pavimentação, desde que as características do solo e a profundidade do lençol freático sejam compatíveis com a infiltração.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Escoamento concentrado junto a vias; redução da infiltração; transporte de sedimentos.',
   'Infiltração distribuída quando adequada; contribuição para a recarga local com controle da qualidade da água.',
   'Contribuição para reduzir alagamentos localizados; integração discreta a vias, calçadas e áreas livres; melhoria das condições de circulação nos pontos atendidos; preservação de usos superficiais compatíveis com o projeto.',
   'Redução potencial de gastos com danos por alagamentos; menor demanda por ampliação da drenagem convencional; possibilidade de implantação gradual, integrada a obras de urbanização e pavimentação.',
   'Solos pouco permeáveis ou contaminados; lençol freático raso; terrenos instáveis; proximidade de fundações e redes sem avaliação técnica. Não deve receber esgoto; exige controle de sedimentos e extravasamento seguro.', 'Lote / Logradouro, Praça / Área livre, Logradouro / Via, Equipamento público / Área institucional',
   'Bordas de vias, calçadas, estacionamentos e limites de lotes, em faixas com solo permeável e lençol freático suficientemente profundo.', 'Média', 'Média', 'R$ 297,00/m de trincheira (≈ R$ 132,00/m³)', 'm³', 'Concluído', 'Pendente'),
  (8, 1, 'pavimento-permeavel-ou-piso-drenante', 'Pavimento permeável ou piso drenante', 8, 'Revestimento que permite a passagem da água por sua superfície até camadas granulares inferiores, onde ocorre o armazenamento temporário e, conforme a configuração, a infiltração no solo ou a condução por drenos. Pode ser utilizado em calçadas, estacionamentos, praças, áreas de manobra e vias de baixo tráfego, reduzindo a impermeabilização e contribuindo para o controle do escoamento superficial. Atua como solução complementar à drenagem convencional e pode ser integrado a jardins de chuva, biovaletas e arborização urbana.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Impermeabilização do solo; aumento do escoamento superficial; redução da infiltração.',
   'Redução do escoamento superficial; armazenamento temporário da água; diminuição da área impermeável conectada à rede; infiltração quando prevista e adequada ao terreno.',
   'Redução de empoçamentos; melhoria das condições de circulação; qualificação de calçadas, praças e estacionamentos.',
   'Redução potencial de danos por alagamentos; menor demanda sobre a drenagem convencional; integração das funções de pavimentação e armazenamento de águas pluviais.',
   'Tráfego e cargas incompatíveis com o dimensionamento; elevado aporte de sedimentos ou ausência de limpeza. A infiltração exige avaliação em solos contaminados, pouco permeáveis ou com lençol freático raso.', 'Lote / Logradouro, Logradouro / Via, Praça / Área livre, Equipamento público / Área institucional',
   'Estacionamentos, calçadas, praças, vias de baixo tráfego e áreas de manobra, conforme as cargas previstas no projeto.', 'Baixa', 'Média', 'R$ 122,00 a R$ 169,00/m²', 'm²', 'Concluído', 'Pendente'),
  (9, 1, 'bacia-de-detencao', 'Bacia de Detenção', 9, 'Depressão ou reservatório projetado para armazenar temporariamente as águas pluviais e liberá-las de forma controlada, reduzindo os picos de vazão e a sobrecarga do sistema de drenagem. Permanece normalmente seco entre os eventos de chuva e pode ser integrado a parques e espaços públicos, desde que sejam previstas condições adequadas de drenagem, segurança e manutenção.', 3, (select id from public.sbn_grupo_funcional where nome = 'Retenção e armazenamento'),
   null, 'Picos elevados de vazão; insuficiência de armazenamento pluvial; alagamentos a jusante.',
   'Armazenamento temporário das águas pluviais; amortecimento dos picos de vazão; redução da sobrecarga da drenagem a jusante; integração com vegetação e funções ambientais quando prevista no projeto.',
   'Contribuição para reduzir alagamentos e inundações; proteção de moradias, vias e equipamentos; possibilidade de lazer e convivência nos períodos secos; qualificação paisagística dos espaços públicos.',
   'Redução potencial de danos por inundações; menor necessidade de ampliação da drenagem a jusante; aproveitamento da mesma área para armazenamento de água e uso público; integração de investimentos hidráulicos e urbanos.',
   'Falta de área ou de condições para esvaziamento e extravasamento seguros; influência do lençol freático e dos níveis de jusante sem avaliação hidráulica; usos incompatíveis com inundação temporária. Não deve receber esgoto.', 'Lote / Logradouro, Praça / Área livre, Bacia / Sistema hídrico',
   'Áreas livres conectadas à macrodrenagem, parques e espaços públicos com capacidade para armazenar temporariamente as águas pluviais e liberá-las de forma controlada.', 'Alta', 'Média', 'R$ 700,00/m³ de reservação, mais R$ 300,00/m² de infraestrutura verde e equipamentos públicos, além da aquisição da área', 'm²', 'Concluído', 'Pendente'),
  (10, 1, 'bacia-de-retencao', 'Bacia de Retenção', 10, 'Reservatório que mantém uma lâmina d’água permanente e dispõe de volume adicional para armazenar parte do escoamento durante as chuvas, reduzindo os picos de vazão. Pode incorporar vegetação marginal e áreas filtrantes, contribuindo para a retenção de sedimentos, a melhoria da qualidade da água e a criação de habitats aquáticos. Sua implantação depende da disponibilidade de área e de condições que permitam manter a lâmina d’água e controlar a qualidade da água armazenada.', 3, (select id from public.sbn_grupo_funcional where nome = 'Retenção e armazenamento'),
   null, 'Picos elevados de vazão; degradação da qualidade da água; perda de habitats aquáticos e marginais.',
   'Amortecimento dos picos de vazão; retenção de sedimentos; melhoria da qualidade da água por sedimentação e processos biológicos; criação de habitats aquáticos e marginais; integração com áreas vegetadas.',
   'Contribuição para reduzir alagamentos e inundações; qualificação paisagística de parques e áreas verdes; oportunidades de lazer, contemplação e educação ambiental, conforme as condições de segurança.',
   'Redução potencial de danos por inundações; menor sobrecarga da drenagem a jusante; redução de custos de desassoreamento nos corpos receptores; integração de funções hidráulicas, ambientais e de lazer em um mesmo investimento.',
   'Falta de área disponível ou de condições para manter a lâmina d’água permanente; ausência de saída controlada e extravasamento seguro; aporte excessivo de sedimentos e poluentes; níveis do lençol freático e das lagoas sem avaliação hidráulica. Não deve receber esgoto sem tratamento.', 'Praça / Área livre, Parque / Área verde, Bacia / Sistema hídrico',
   'Parques e áreas livres conectados à macrodrenagem, com espaço para reservação e condições para manter lâmina d’água permanente.', 'Alta', 'Alta', 'R$ 700,00 por unidade de reservação*, mais R$ 300,00/m² de infraestrutura verde e equipamentos públicos', 'm²', 'Concluído', 'Pendente'),
  (11, 1, 'bacia-de-infiltracao', 'Bacia de Infiltração', 11, 'Depressão rasa que armazena temporariamente as águas pluviais e promove sua infiltração no solo, reduzindo o escoamento superficial e favorecendo a recarga subterrânea. Pode ser integrada a parques, áreas verdes e outros espaços livres, desde que o solo apresente permeabilidade adequada e haja distância suficiente entre o fundo da estrutura e o nível máximo do lençol freático. Não mantém lâmina d’água permanente e exige controle do aporte de sedimentos para evitar a obstrução dos poros do solo.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Excesso de escoamento superficial; redução da infiltração; aumento das vazões a jusante.',
   'Redução do volume escoado e dos picos de vazão; contribuição para a recarga subterrânea; melhoria da qualidade da água quando compatível com o solo e a qualidade afluente; integração com áreas vegetadas.',
   'Contribuição para reduzir alagamentos; qualificação paisagística de áreas livres; integração a parques e percursos de uso público, conforme as condições de segurança; oportunidades de educação ambiental.',
   'Redução potencial de danos por alagamentos; menor demanda sobre a drenagem convencional; aproveitamento de áreas livres para armazenamento e infiltração; integração a projetos de parques e requalificação urbana.',
   'Solos pouco permeáveis, saturados ou contaminados; lençol freático raso; risco de instabilidade ou contaminação subterrânea; elevado aporte de sedimentos sem pré-tratamento; ausência de extravasamento seguro. Não deve receber esgoto.', 'Praça / Área livre, Parque / Área verde, Bacia / Sistema hídrico',
   'Parques e áreas livres com solo permeável, espaço para armazenamento temporário e afastamento adequado do lençol freático.', 'Média', 'Média', 'R$ 700,00/m³ de reservação, mais R$ 300,00/m² de infraestrutura verde e equipamentos públicos, além da aquisição da área', 'm²', 'Concluído', 'Pendente'),
  (12, 1, 'reservatorio-anfibio', 'Reservatório Anfíbio', 12, 'Sistema de reservação que combina o armazenamento temporário das águas pluviais com áreas vegetadas e espaços destinados ao uso público em períodos secos. Durante as chuvas, recebe e armazena parte do escoamento, contribuindo para o controle de cheias; nos períodos secos, áreas compatíveis com a alternância entre inundação e secagem podem ser utilizadas para lazer e convivência. Conforme o projeto, pode integrar a recuperação de cursos d’água e várzeas, o tratamento da água e a vegetação, dependendo da disponibilidade de espaço e das condições hidráulicas e ambientais locais.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Cheias e picos de vazão; insuficiência de áreas de armazenamento; degradação de áreas sujeitas à inundação.',
   'Amortecimento dos picos de vazão; retenção de resíduos e sedimentos; melhoria da qualidade da água conforme os dispositivos incorporados; recuperação de áreas vegetadas e funções ecológicas.',
   'Contribuição para reduzir inundações; criação de espaços de lazer, esportes e convivência nos períodos secos; qualificação paisagística; oportunidades de educação ambiental.',
   'Redução potencial de danos por inundações; aproveitamento da mesma área para reservação e uso público; integração de investimentos em drenagem, recuperação ambiental e lazer.',
   'Falta de área, esvaziamento ou extravasamento seguros; interferência do lençol freático e dos níveis de jusante sem avaliação; elevada carga poluente sem controle; usos e equipamentos incompatíveis com inundação temporária.', 'Praça / Área livre, Parque / Área verde, Bacia / Sistema hídrico',
   'Áreas livres conectadas à macrodrenagem, com espaço para reservação e usos públicos compatíveis com a alternância entre cheia e seca.', 'Alta', 'Média', 'R$ 700,00/m³ de reservação*', 'm³', 'Concluído', 'Pendente'),
  (13, 1, 'wetland-construido-para-tratamento-de-aguas-pluviais', 'Wetland construído para tratamento de águas pluviais', 13, 'Sistema vegetado que utiliza áreas alagáveis e substratos filtrantes para receber e tratar águas, contribuindo para o armazenamento temporário do escoamento pluvial, a retenção de sedimentos e a melhoria da qualidade da água. Sua implantação pode integrar a drenagem urbana a áreas verdes, reduzindo picos de vazão e favorecendo a conexão entre os sistemas de infraestrutura hídrica e ambiental.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Poluição difusa; aporte de sedimentos e nutrientes; degradação da qualidade da água.',
   'Retenção de parte dos sedimentos e poluentes transportados pelo escoamento; melhoria da qualidade da água, conforme o projeto e a carga afluente; armazenamento temporário de águas pluviais; criação de habitat vegetado.',
   'Qualificação paisagística de áreas públicas; oportunidades de educação ambiental; melhoria da relação entre espaços urbanos e sistemas hídricos, quando integrado a áreas verdes acessíveis.',
   'Possível redução de custos associados ao assoreamento e à degradação hídrica; proteção dos dispositivos e corpos hídricos a jusante; integração de funções de tratamento, paisagem e lazer em um mesmo investimento.',
   'Não é indicado receber esgoto doméstico sem tratamento ou águas com contaminantes que comprometam o sistema. Exige avaliação da qualidade e da quantidade do escoamento, pré-tratamento quando necessário, área disponível e plano de manutenção. Deve-se evitar sua implantação em áreas úmidas naturais ou em locais onde a intervenção possa degradar ecossistemas existentes.', 'Praça / Área livre, Parque / Área verde, Equipamento público / Área institucional, Bacia / Sistema hídrico',
   'Áreas livres, parques e pontos de lançamento da drenagem, para tratar águas pluviais antes de sua chegada a canais, lagoas e outros corpos hídricos.', 'Média', 'Média', 'R$ 147,00/m² (escala de parque) a R$ 800,00/m² (pequena escala)*', 'm²', 'Concluído', 'Pendente'),
  (14, 1, 'bacia-de-sedimentacao', 'Bacia de Sedimentação', 14, 'Estrutura que reduz a velocidade do escoamento para favorecer a deposição dos sólidos suspensos transportados pela água, diminuindo o aporte de sedimentos aos corpos hídricos e protegendo as etapas seguintes de tratamento. sólidos suspensos. É indispensável assegurar o acesso de frotas e equipamentos para a manutenção preventiva das bacias.', 3, (select id from public.sbn_grupo_funcional where nome = 'Drenagem, filtragem e infiltração'),
   null, 'Transporte de sedimentos; assoreamento de canais e corpos hídricos; degradação de habitats aquáticos.',
   'Redução do aporte de sedimentos e poluentes associados às partículas; contribuição para diminuir o assoreamento; proteção de wetlands e jardins filtrantes contra colmatação; integração com vegetação marginal.',
   'Contribuição para preservar o funcionamento da drenagem; melhoria das condições ambientais do entorno; qualificação paisagística quando integrada a áreas vegetadas; oportunidades de educação ambiental.',
   'Possível redução dos custos de desassoreamento a jusante; proteção dos materiais filtrantes e das etapas seguintes de tratamento; concentração da retirada de sedimentos em local acessível; redução potencial de intervenções corretivas na drenagem.',
   'Ausência de acesso para limpeza ou destinação adequada dos sedimentos; falta de encaminhamento seguro dos excedentes; recebimento de cargas incompatíveis com o projeto. Não substitui o tratamento de esgoto nem remove todos os contaminantes.', 'Margem / Canal, Margem / Lagoa, Parque / Área verde, Bacia / Sistema hídrico',
   'Pontos anteriores aos lançamentos em canais e lagoas ou à entrada de wetlands e jardins filtrantes, especialmente a jusante de áreas produtoras de sedimentos.', 'Média', 'Alta', 'R$ 700,00/m³ de reservação*', 'm³', 'Concluído', 'Pendente'),
  (15, 2, 'terraco-de-chuva', 'Terraço de chuva', 1, 'Estrutura transversal ao declive que recebe e armazena parte do escoamento superficial, favorecendo sua infiltração quando compatível com a estabilidade da encosta. Deve incorporar encaminhamento seguro dos excedentes.', 3, (select id from public.sbn_grupo_funcional where nome = 'Estabilidade do terreno e controle da erosão'),
   'Movimentação de Massa', 'Concentração do escoamento nas encostas; erosão superficial; carreamento de sedimentos para áreas ocupadas e drenagem.',
