  (16, 2, 'canal-de-cintura', 'Canal de cintura', 2, 'Canal que intercepta o escoamento das partes altas e o conduz até pontos seguros de lançamento, reduzindo sua concentração sobre encostas, taludes e áreas ocupadas.', 3, (select id from public.sbn_grupo_funcional where nome = 'Estabilidade do terreno e controle da erosão'),
