  (17, 2, 'vegetacao-e-recomposicao-florestal-com-especies-nativas-da-m', 'Vegetação e recomposição florestal com espécies nativas da Mata Atlântica', 3, 'Conservação da vegetação existente e recuperação de cobertura florestal por regeneração natural, plantio de espécies nativas ou combinação dessas estratégias. A cobertura, a serapilheira e as raízes protegem e reforçam as camadas superficiais do solo.', 2, (select id from public.sbn_grupo_funcional where nome = 'Estabilidade do terreno e controle da erosão'),
