  (19, 2, 'grade-viva', 'Grade viva', 5, 'Grade de madeira ancorada ao terreno e preenchida com solo e material vegetal vivo, que acompanha a superfície da encosta. Combina suporte inicial do madeiramento com proteção e reforço superficial proporcionados pela vegetação.', 3, (select id from public.sbn_grupo_funcional where nome = 'Estabilidade do terreno e controle da erosão'),
