-- ----------------------------------------------- 5. SEGURANÇA (RLS: leitura)
alter table public.tema_estrategico enable row level security;
alter table public.areas_prioritarias enable row level security;
alter table public.area_tema enable row level security;
alter table public.sbn_grupo_funcional enable row level security;
alter table public.sbn_funcao enable row level security;
alter table public.sbn_solucao enable row level security;
alter table public.sbn_solucao_funcao enable row level security;

drop policy if exists "leitura publica tema_estrategico" on public.tema_estrategico;
create policy "leitura publica tema_estrategico" on public.tema_estrategico for select to anon, authenticated using (true);
drop policy if exists "leitura publica areas_prioritarias" on public.areas_prioritarias;
create policy "leitura publica areas_prioritarias" on public.areas_prioritarias for select to anon, authenticated using (true);
drop policy if exists "leitura publica area_tema" on public.area_tema;
create policy "leitura publica area_tema" on public.area_tema for select to anon, authenticated using (true);
drop policy if exists "leitura publica sbn_grupo_funcional" on public.sbn_grupo_funcional;
create policy "leitura publica sbn_grupo_funcional" on public.sbn_grupo_funcional for select to anon, authenticated using (true);
drop policy if exists "leitura publica sbn_funcao" on public.sbn_funcao;
create policy "leitura publica sbn_funcao" on public.sbn_funcao for select to anon, authenticated using (true);
drop policy if exists "leitura publica sbn_solucao" on public.sbn_solucao;
create policy "leitura publica sbn_solucao" on public.sbn_solucao for select to anon, authenticated using (true);
drop policy if exists "leitura publica sbn_solucao_funcao" on public.sbn_solucao_funcao;
create policy "leitura publica sbn_solucao_funcao" on public.sbn_solucao_funcao for select to anon, authenticated using (true);

-- Escrita bloqueada para o público (a chave do site é apenas identificadora).
revoke insert, update, delete, truncate on public.tema_estrategico from anon, authenticated;
grant select on public.tema_estrategico to anon, authenticated;
revoke insert, update, delete, truncate on public.areas_prioritarias from anon, authenticated;
grant select on public.areas_prioritarias to anon, authenticated;
revoke insert, update, delete, truncate on public.area_tema from anon, authenticated;
grant select on public.area_tema to anon, authenticated;
revoke insert, update, delete, truncate on public.sbn_grupo_funcional from anon, authenticated;
grant select on public.sbn_grupo_funcional to anon, authenticated;
revoke insert, update, delete, truncate on public.sbn_funcao from anon, authenticated;
grant select on public.sbn_funcao to anon, authenticated;
revoke insert, update, delete, truncate on public.sbn_solucao from anon, authenticated;
grant select on public.sbn_solucao to anon, authenticated;
revoke insert, update, delete, truncate on public.sbn_solucao_funcao from anon, authenticated;
grant select on public.sbn_solucao_funcao to anon, authenticated;

-- ------------------------------------------- 6. PUBLICAÇÃO PARA A WEB (4326)
-- security_invoker = true: a view respeita o RLS de quem consulta, e não o do dono.
create or replace view public.vw_areas_prioritarias
  with (security_invoker = true) as
select a.num_area,
       a.area_ha,
       coalesce(array_agg(t.tema_id order by t.tema_id) filter (where t.tema_id is not null),
              '{}'::smallint[]) as temas,
       ST_Transform(a.geom, 4326) as geom
  from public.areas_prioritarias a
  left join public.area_tema t on t.num_area = a.num_area
 group by a.num_area, a.area_ha, a.geom;

grant select on public.vw_areas_prioritarias to anon, authenticated;

-- Funções com ARGUMENTO TIPADO: é assim que se faz consulta parametrizada no
-- PostgREST. O valor nunca é concatenado em texto de SQL.
create or replace function public.sbn_do_tema(p_tema smallint)
returns table (id smallint, slug text, nome text, descricao text,
               grupo_funcional text, status_conteudo text)
language sql stable security invoker set search_path = public, extensions as $$
  select s.id, s.slug, s.nome, s.descricao, g.nome, s.status_conteudo
    from public.sbn_solucao s
    left join public.sbn_grupo_funcional g on g.id = s.grupo_funcional_id
   where s.tema_id = p_tema
   order by s.ordem;
$$;

create or replace function public.temas_da_area(p_num_area smallint)
returns table (id smallint, nome text, nome_curto text, cor text, n_solucoes bigint)
language sql stable security invoker set search_path = public, extensions as $$
  select t.id, t.nome, t.nome_curto, t.cor, count(s.id)
    from public.area_tema at
    join public.tema_estrategico t on t.id = at.tema_id
    left join public.sbn_solucao s on s.tema_id = t.id
   where at.num_area = p_num_area
   group by t.id, t.nome, t.nome_curto, t.cor, t.ordem
   order by t.ordem;
$$;

-- Ficha completa numa só chamada (evita 3 idas ao servidor por solução).
create or replace function public.ficha_sbn(p_slug text)
returns json
language sql stable security invoker set search_path = public, extensions as $$
  select to_json(x) from (
    select s.id, s.slug, s.nome, s.ordem, s.descricao, s.tipologia,
           t.id as tema_id, t.nome as tema_nome, t.cor as tema_cor,
           g.nome as grupo_funcional,
           s.ameaca_climatica, s.desafio_ambiental,
           s.beneficios_ambientais, s.beneficios_sociais, s.beneficios_economicos,
           s.restricoes, s.escala_aplicacao, s.aplicacao,
           s.complexidade, s.manutencao, s.custo, s.custo_unidade,
           s.tempo_resultado, s.referencias, s.ilustracao_url,
           s.status_conteudo, s.status_ilustracao,
           (select coalesce(array_agg(f.id order by f.ordem), '{}'::smallint[])
              from public.sbn_solucao_funcao sf
              join public.sbn_funcao f on f.id = sf.funcao_id
             where sf.solucao_id = s.id) as funcoes
      from public.sbn_solucao s
      join public.tema_estrategico t on t.id = s.tema_id
      left join public.sbn_grupo_funcional g on g.id = s.grupo_funcional_id
     where s.slug = p_slug) x;
$$;

-- Vocabulário das 20 funções, para desenhar a grade da ficha.
create or replace function public.sbn_funcoes()
returns table (id smallint, ordem smallint, nome text)
language sql stable security invoker set search_path = public, extensions as $$
  select f.id, f.ordem, f.nome from public.sbn_funcao f order by f.ordem;
$$;

grant execute on function public.sbn_do_tema(smallint) to anon, authenticated;
grant execute on function public.temas_da_area(smallint) to anon, authenticated;
grant execute on function public.ficha_sbn(text) to anon, authenticated;
grant execute on function public.sbn_funcoes() to anon, authenticated;

notify pgrst, 'reload schema';

-- ============================================================================
-- CONFERÊNCIA — rode e compare com os números esperados
-- ============================================================================
select
  (select count(*) from public.areas_prioritarias)                  as areas,          -- esperado 60
  (select count(*) from public.area_tema)                           as vinculos,       -- esperado 90
  (select count(distinct num_area) from public.area_tema)           as areas_com_tema, -- esperado 60
  (select count(*) from public.sbn_solucao)                         as solucoes,       -- esperado 43
  (select count(*) from public.sbn_solucao_funcao)                  as func_ligadas,   -- esperado 169
  (select count(*) from public.areas_prioritarias
    where not ST_IsValid(geom))                                     as geom_invalidas, -- esperado 0
  (select round(sum(area_ha)::numeric, 1) from public.areas_prioritarias) as area_total_ha; -- esperado 3060.5

-- Soluções por tema (esperado: 1=14, 2=13, 3=6, 4=6, 5=4)
select t.id, t.nome_curto, count(s.id) as solucoes
  from public.tema_estrategico t left join public.sbn_solucao s on s.tema_id = t.id
 group by t.id, t.nome_curto, t.ordem order by t.ordem;

